/**
 * Real, correctly-licensed (SIL OFL) TrueType font data, embedded for
 * jsPDF -- generated once via a Node script, not converted at runtime.
 * Source: @fontsource/* npm packages (the same fonts the live app
 * already loads via tokens.css --font-display/--font-mono/--font-body),
 * losslessly decompressed from their real WOFF2 files to TTF with
 * wawoff2 (a lossless format conversion, not a re-render or
 * approximation -- WOFF2 is a compressed wrapper around the exact
 * same SFNT table data jsPDF needs as a raw TTF). Verified end-to-end
 * before adoption: a real jsPDF doc was generated with each of these
 * embedded and read back to confirm the actual glyphs render, not a
 * silent Helvetica fallback.
 *
 * To regenerate (e.g. to add a weight): npm install --no-save
 * @fontsource/space-grotesk @fontsource/inter @fontsource/jetbrains-mono
 * wawoff2, then decompress the specific -latin-<weight>-normal.woff2
 * file with wawoff2.decompress() and base64-encode the result.
 */

export const SpaceGroteskBold = "";
export const SpaceGroteskSemiBold = "";
export const InterRegular = "";
export const InterSemiBold = "";
export const JetBrainsMonoRegular = "";
export const JetBrainsMonoMedium = "";
export const JetBrainsMonoBold = "";
